@namespace sv_4df049035f9f4550aea02b71c09a0e2c.Components.Pages.Apply

<fieldset class="work-entry-editor">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label for="company-@Index">Company Name *</label>
        <input id="company-@Index" type="text" @bind="Entry.Company" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="title-@Index">Job Title *</label>
        <input id="title-@Index" type="text" @bind="Entry.Title" @bind:event="oninput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label for="start-@Index">Start Date *</label>
            <input id="start-@Index" type="date" @bind="Entry.StartDate" />
        </div>

        <div class="form-group">
            <label>
