@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();

    private readonly PersonalInfoStep.PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryEditor.WorkEntryModel> _workEntries = new() { new() };
    private readonly List<ReferenceEditor.ReferenceModel> _references = new() { new(), new() };
    private string _coverLetter = "";

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        _currentStep--;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company,
                e.Title,
                e.StartDate,
                e.IsCurrent ? null : e.EndDate,
                e.Description
