        );

        var references = _references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            workHistory,
            references,
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
